WITH "cte_population_density" AS (SELECT *, CASE WHEN "land_area" = 0 THEN NULL ELSE CAST("total_population" AS NUMERIC) / "land_area" * 1 END AS "population_density" FROM _base)
SELECT "province", "population_density" FROM (SELECT "province", SUM(area_km2) AS "land_area", SUM(count) AS "total_population" FROM (SELECT * FROM (SELECT * FROM "reference"."geography_areas" AS "t_geography_data") AS _left JOIN (SELECT * FROM "census"."population_data" AS "t_population") AS _right ON _left."geo_code" = _right."geo_code" AND _left."geo_level" = _right."geo_level") AS _agg GROUP BY "province") AS _proj
